using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Autodesk.AutoCAD.Runtime;
using Autodesk.AutoCAD.DatabaseServices;
using Autodesk.AutoCAD.Geometry;
using AcApp=Autodesk.AutoCAD.ApplicationServices.Core.Application;
using JsonUtil=AICad.Contracts.Json;
[assembly:CommandClass(typeof(AICad.Bridge.ReviewFlowTests))]
namespace AICad.Bridge;
public sealed class ReviewFlowTests {
 [CommandMethod("AICADPLANPREVIEWTEST",CommandFlags.Modal|CommandFlags.NoUndoMarker)]public void PlanPreview(){string root=Environment.GetEnvironmentVariable("AICAD_TEST_ROOT")??"";if(!Path.IsPathRooted(root)||!File.Exists(Path.Combine(root,".aicad-test-root")))throw new InvalidOperationException("Isolated test root required.");string id=Environment.GetEnvironmentVariable("AICAD_TEST_PLAN")??"";var record=Plugin.Current!.Plans.Read(AICad.Contracts.Json.Id(id));try{var ctx=Plugin.Current!.Context;var doc=AcApp.DocumentManager.MdiActiveDocument;string before=ctx.Revision(doc);using var scene=new NativePreviewScene(record.Plan);string after=ctx.Revision(doc);JsonUtil.Atomic(Path.Combine(root,"actual-plan-preview.json"),new{passed=before==after,count=scene.Entities.Count,before,after,causes=ctx.RevisionCauses});}catch(System.Exception e){JsonUtil.Atomic(Path.Combine(root,"actual-plan-preview.json"),new{passed=false,error=e.ToString()});}}
 [CommandMethod("AICADREVIEWFLOWTEST",CommandFlags.Modal|CommandFlags.NoUndoMarker)]public void Run(){
 string root=Environment.GetEnvironmentVariable("AICAD_TEST_ROOT")??"";
 if(!Path.IsPathRooted(root)||!File.Exists(Path.Combine(root,".aicad-test-root")))throw new InvalidOperationException("Isolated test root required.");
 var results=new List<object>();int failed=0;void Test(string name,Action action){try{action();results.Add(new{name,passed=true});}catch(System.Exception e){failed++;results.Add(new{name,passed=false,error=e.ToString()});}}
 var d=AcApp.DocumentManager.MdiActiveDocument;var context=Plugin.Current!.Context;
 Test("Apply command has no implicit pre-validation Undo marker",()=>{var a=(CommandMethodAttribute)Attribute.GetCustomAttribute(typeof(Commands).GetMethod("Apply"),typeof(CommandMethodAttribute));if((a.Flags&CommandFlags.NoUndoMarker)==0)throw new System.Exception("Missing NoUndoMarker");});
 Test("Viewport navigation does not invalidate geometry revision",()=>{string before=context.Revision(d);using(var tx=d.Database.TransactionManager.StartTransaction()){var vt=(ViewportTable)tx.GetObject(d.Database.ViewportTableId,OpenMode.ForRead);var v=(ViewportTableRecord)tx.GetObject(vt["*Active"],OpenMode.ForWrite);v.Width+=10;tx.Commit();}if(context.Revision(d)!=before)throw new System.Exception("Viewport changed geometry revision");});
 Test("Dimension preview keeps target DWG revision unchanged",()=>{var template=new AICad.Contracts.ContentStore(Plugin.Current!.Config.ContentRoot).Template("ARCHITECTURE");var plan=new AICad.Contracts.DrawingPlan{Template=template,Scope=new(){new(-10000,-10000),new(30000,-10000),new(30000,20000),new(-10000,20000)},Operations=new(){new(){Kind="add_dimension",Layer="A-DIM",Points=new(){new(0,0),new(16000,0),new(0,-600)}}}};string before=context.Revision(d);using var scene=new NativePreviewScene(plan);if(context.Revision(d)!=before)throw new System.Exception("Staged dimension modified active target DB: "+before+" -> "+context.Revision(d));});
 ObjectId line=ObjectId.Null;
 Test("Explicit Undo group commits geometry and one Undo removes it",()=>{d.Editor.Command("_.UNDO","_BEGIN");try{using(var tx=d.Database.TransactionManager.StartTransaction()){var bt=(BlockTable)tx.GetObject(d.Database.BlockTableId,OpenMode.ForRead);var ms=(BlockTableRecord)tx.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForWrite);var e=new Line(new Point3d(0,0,0),new Point3d(10,0,0));line=ms.AppendEntity(e);tx.AddNewlyCreatedDBObject(e,true);tx.Commit();}}finally{d.Editor.Command("_.UNDO","_END");}if(line.IsErased)throw new System.Exception("Line not committed");d.Editor.Command("_.U");if(!line.IsErased)throw new System.Exception("One Undo did not remove line");});
 Test("Real entity edit invalidates revision",()=>{string before=context.Revision(d);using(var tx=d.Database.TransactionManager.StartTransaction()){var bt=(BlockTable)tx.GetObject(d.Database.BlockTableId,OpenMode.ForRead);var ms=(BlockTableRecord)tx.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForWrite);var e=new Line(new Point3d(20,0,0),new Point3d(30,0,0));ms.AppendEntity(e);tx.AddNewlyCreatedDBObject(e,true);tx.Commit();}if(context.Revision(d)==before)throw new System.Exception("Entity edit was ignored");});
 Test("Source frame and independent output point remain in the same DWG",()=>{string docId=context.Info(d).DocumentId;SourceTaskCommands.Create(d,100000,200000,21000,10000,"ANCHOR_TEST","SOURCE_FLOORPLAN_QUANGANH","QUANGANH_FLOORPLAN",Guid.NewGuid().ToString("N"));var before=Reader.Scan(d).Single(t=>t.TaskId=="ANCHOR_TEST");if(before.OutputPoint==null||before.OutputPoint.X!=100000)throw new System.Exception("Output anchor missing");string revision=context.Revision(d);using(var tx=d.Database.TransactionManager.StartTransaction()){var bt=(BlockTable)tx.GetObject(d.Database.BlockTableId,OpenMode.ForRead);var ms=(BlockTableRecord)tx.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForRead);foreach(ObjectId id in ms){if(tx.GetObject(id,OpenMode.ForRead) is not BlockReference block)continue;var def=(BlockTableRecord)tx.GetObject(block.BlockTableRecord,OpenMode.ForRead);if(def.Name!="AI_OUTPUT_POINT")continue;block.UpgradeOpen();block.Position=new Point3d(135000,240000,0);}tx.Commit();}var after=Reader.Scan(d).Single(t=>t.TaskId=="ANCHOR_TEST");if(after.OutputPoint?.X!=135000||after.OutputPoint.Y!=240000||after.Scope[0].X!=100000||context.Info(d).DocumentId!=docId)throw new System.Exception("Anchor move changed frame or target document");try{context.Resolve(docId,revision);throw new System.Exception("Anchor move did not invalidate revision");}catch(AICad.Contracts.CadException e)when(e.Code=="STALE_REVISION"){}var output=AICad.Geometry.TaskPlacement.OutputScope(after);if(output[0].X!=135000||output[0].Y!=240000)throw new System.Exception("Output scope ignored anchor");});
 JsonUtil.Atomic(Path.Combine(root,"review-flow-results.json"),new{passed=results.Count-failed,total=results.Count,failed,cases=results});
 }
}
